window.WorkspaceSettings=(()=>{
 const key='project-dashboard.preferences.v1',defaults={locale:'en-US',dateFormat:'friendly',home:'portfolio',density:'comfortable',motion:true,pageSize:'10',member:''};
 function read(){try{const p={...defaults,...JSON.parse(localStorage.getItem(key)||'{}')};for(const [k,values] of Object.entries({locale:['en-US','ja-JP','zh-CN'],dateFormat:['friendly','iso'],home:['portfolio','weekly','risks','projects'],density:['comfortable','compact'],pageSize:['10','20','50']}))if(!values.includes(p[k]))p[k]=defaults[k];p.motion=typeof p.motion==='boolean'?p.motion:true;p.member=typeof p.member==='string'?p.member:'';return p}catch{return {...defaults}}}
 function apply(){const p=read();document.body.classList.toggle('settings-compact',p.density==='compact');document.body.classList.toggle('settings-reduced-motion',!p.motion)}
 function date(value){if(!value)return '—';const p=read();if(p.dateFormat==='iso')return value.slice(0,10);const d=new Date(value.slice(0,10)+'T12:00:00');return Number.isNaN(d.getTime())?'—':d.toLocaleDateString(p.locale,{month:'short',day:'numeric',year:'numeric'})}
 function mount(container,{members,avatar,editMember,open,exportData}){let section='General',draft=read();
 const select=(name,label,values)=>`<label>${label}<select name="${name}">${values.map(([value,text])=>`<option value="${esc(value)}" ${draft[name]===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
 function draw(){const member=members.find(m=>m.id===draft.member);const general=`<h2>General Settings</h2><p class="muted">Preferences are saved in this browser on this device.</p><h3>Language & Region</h3><div class="st-fields">${select('locale','Date language',[['en-US','English'],['ja-JP','日本語'],['zh-CN','中文']])}${select('dateFormat','Date Format',[['friendly','Localized date'],['iso','YYYY-MM-DD']])}</div><p class="pf-caption">Changes date labels in project dashboards and weekly reports. Interface labels remain English. Project dates are calendar dates, so no timezone conversion is applied.</p><h3>Display Preferences</h3><div class="st-fields">${select('home','Default View',[['portfolio','Portfolio'],['weekly','Weekly Reports'],['risks','Risk Management'],['projects','Projects']])}${select('pageSize','Risks per page',[['10','10'],['20','20'],['50','50']])}</div>`;
 const appearance=`<h2>Appearance</h2><p class="muted">Adjust spacing and motion throughout the workspace.</p>${select('density','Display density',[['comfortable','Comfortable'],['compact','Compact']])}<label class="st-toggle"><span>Enable animations</span><input type="checkbox" name="motion" ${draft.motion?'checked':''}></label><p class="pf-caption">The current light workspace and dark sidebar theme is used across dashboards.</p>`;
 const profile=`<h2>Member Profile</h2><p class="muted">Select a workspace member to view or edit their shared profile. This selection is not a sign-in identity.</p>${select('member','Member',[['','Select a member'],...members.map(m=>[m.id,m.name])])}${member?`<div class="st-person">${avatar(member)}<div><h3>${esc(member.name)}</h3><p>${esc(member.role||'')}</p><p>${esc(member.email||'No email saved')}</p></div></div><button type="button" class="secondary" data-st-edit>Edit member profile</button>`:''}`;
 const info={Notifications:['Notifications','Email, push notifications, and scheduled digests are not configured in this application. Task changes remain available in workspace activity.'],Security:['Security','This workspace does not provide individual account login or password management. Production access controls are managed on the server. Selecting a member profile does not change permissions.'],Integrations:['Integrations','No external accounts are connected through this application. GitHub deployment access is separate from application integrations.'],Billing:['Billing','This self-hosted workspace has no subscription or billing service.'],Team:['Team & Permissions','Manage teams, members, and project assignments. Application role-based access restrictions are not implemented.'],Advanced:['Data & Preferences','Export workspace data or reset this browser’s preferences. Exports do not replace database and uploaded-file backups.']};
 const body=section==='General'?general:section==='Appearance'?appearance:section==='Profile'?profile:`<h2>${info[section][0]}</h2><p class="st-info">${info[section][1]}</p>${section==='Team'?'<button type="button" class="primary" data-st-team>Manage teams & members</button>':''}${section==='Advanced'?'<button type="button" class="secondary" data-st-export>Export workspace data</button><button type="button" class="secondary" data-st-reset>Reset browser preferences</button>':''}`;
 container.innerHTML=`<div class="pf-heading"><div><h1><span class="fa-solid fa-gear" aria-hidden="true"></span> Settings</h1><p>Manage your preferences and workspace profiles.</p></div></div><div class="st-layout"><div class="panel st-nav">${[['General','gear'],['Profile','user'],['Notifications','bell'],['Appearance','palette'],['Security','shield-halved'],['Integrations','link'],['Billing','credit-card'],['Team','users'],['Advanced','sliders']].map(([name,icon])=>`<button data-st-section="${name}" aria-pressed="${section===name}"><span class="fa-solid fa-${icon}" aria-hidden="true"></span>${name==='Team'?'Team & Permissions':name}</button>`).join('')}</div><form class="panel st-form">${body}<p role="status" class="st-feedback"></p>${['General','Appearance','Profile'].includes(section)?'<div class="st-save"><button type="button" class="secondary" data-st-cancel>Cancel</button><button class="primary" type="submit">Save Changes</button></div>':''}</form><div class="st-side"><section class="panel"><h2>Profile Information</h2>${member?`<div class="st-person">${avatar(member)}<div><b>${esc(member.name)}</b><p>${esc(member.role||'')}</p></div></div><p>${esc(member.email||'No email saved')}</p><button class="text-btn" data-st-edit>Edit profile</button>`:'<p class="st-info">Select a member in Profile to display their details here.</p>'}</section><section class="panel"><h2>Connected Accounts</h2><p class="st-info">No application integrations connected.</p></section><section class="panel"><h2>Data & Privacy</h2><button class="text-btn" data-st-export><span class="fa-solid fa-download" aria-hidden="true"></span> Export workspace data</button><p class="pf-caption">Includes shared workspace data. Uploaded file contents are not included.</p></section></div></div>`;
 container.querySelector('form').onsubmit=e=>{e.preventDefault();try{localStorage.setItem(key,JSON.stringify(draft));apply();container.querySelector('.st-feedback').textContent='Preferences saved on this device.'}catch{container.querySelector('.st-feedback').textContent='Could not save preferences. Browser storage may be unavailable.'}};
 }
 container.onchange=e=>{if(e.target.name){draft[e.target.name]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(e.target.name==='member')draw()}};
 container.onclick=async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.stSection){section=b.dataset.stSection;draw()}if(b.hasAttribute('data-st-cancel')){draft=read();draw()}if(b.hasAttribute('data-st-edit')&&draft.member)editMember(draft.member);if(b.hasAttribute('data-st-team'))open('teams');if(b.hasAttribute('data-st-export')){b.disabled=true;try{await exportData();container.querySelector('.st-feedback').textContent='Workspace export downloaded.'}catch(error){container.querySelector('.st-feedback').textContent='Export failed: '+error.message}finally{b.disabled=false}}if(b.hasAttribute('data-st-reset')){try{localStorage.removeItem(key);draft=read();apply();draw();container.querySelector('.st-feedback').textContent='Browser preferences reset.'}catch{container.querySelector('.st-feedback').textContent='Could not reset browser preferences.'}}};draw();
 }
 return {read,apply,date,mount};
})();
